  $('#requirementsList').addEventListener('click',async e=>{const b=e.target.closest('[data-req-decision]');if(!b||!currentAnalysis)return;const req=currentAnalysis.requirements.find(x=>x.id===b.dataset.req);if(!req)return;const statement=$(`[data-statement="${CSS.escape(req.id)}"]`).value;const acceptanceCriteria=$(`[data-criteria="${CSS.escape(req.id)}"]`).value;const decision=b.dataset.reqDecision;try{const data=new FormData();data.set('status',decision==='Changes requested'?'Needs review':decision);data.set('statement',statement);data.set('acceptance_criteria',acceptanceCriteria);data.set('reviewer_role',$('#approvalRole').value);const response=await fetch(`/api/projects/${encodeURIComponent(currentProjectId)}/requirements/${encodeURIComponent(req.id)}/approval`,{method:'POST',body:data});if(!response.ok)throw new Error((await response.json()).detail||'Could not record requirement review');req.statement=statement;req.acceptanceCriteria=acceptanceCriteria;req.approvalStatus=decision;req.approvalHistory.push({role:$('#approvalRole').value,decision,at:new Date().toISOString()});audit.push({type:'Requirement review',requirementId:req.id,decision,at:new Date().toISOString()});syncRequirementDocuments();renderWorkbench(currentAnalysis);toast(`${req.id}: ${decision}`);}catch(error){toast(error.message);}});
