  form.addEventListener('submit',async(event)=>{event.preventDefault();if(!form.reportValidity())return;const project=collect();const interviewText=Object.entries(interviewAnswers).filter(([,v])=>v.trim()).map(([k,v])=>`${k}: ${v}`).join('\n');const analysisSources=interviewText?[...sources,{id:'INTERVIEW',name:'Stakeholder interview notes',text:interviewText,stakeholder:$('#interviewRole').value,version:'1.0'}]:sources;const button=form.querySelector('[type=submit]');button.disabled=true;button.querySelector('span').textContent='Analyzing sources and requirements…';try{const result=await apiRequest('/api/analyze',{method:'POST',body:JSON.stringify({project,sources:analysisSources,knowledgeBase,useLlm:$('#useLlm').checked})});currentProjectId=result.projectId;currentAnalysis=result.analysis;const s=result.analysis.sdlc;const rec={primary:s.selected,secondary:s.ranked?.[1]?.name||'',hybrid:s.selected.includes('hybrid'),explanation:s.rationale,ranked:s.ranked||[],signals:{uncertainty:s.missingFactors?.length>0},certainty:`${s.readiness}% readiness · ${s.missingFactors?.length||0} factors need confirmation`};currentRecommendation=rec;approvals=[];audit=[{type:'Analysis generated',at:new Date().toISOString()}];const generated=makeDocs(project,rec);const requirementTable='\n\n## Extracted draft requirements\n\n| ID | Categories | Statement | Source | Priority | Approval |\n| --- | --- | --- | --- | --- | --- |\n'+result.analysis.requirements.map(q=>`| ${q.id} | ${q.categories.join(', ')} | ${q.statement.replace(/\|/g,'\\|')} | ${q.sourceName} | ${q.priority} | ${q.approvalStatus} |`).join('\n');const analysisDoc=`\n\n## Issues and clarification queue\n\n${result.analysis.issues.map(i=>`- **${i.type} (${i.severity})** ${i.message} Clarification: ${i.question||'Review with stakeholder.'}`).join('\n')||'No issues flagged.'}`;generated.find(d=>d.id==='srs').content+=requirementTable+analysisDoc;generated.find(d=>d.id==='traceability').content+=requirementTable;generated.find(d=>d.id==='sdlc').content+='\n\n## Analysis factors\n\n'+(s.factors||[]).map(f=>`- **${f.name}:** ${f.value} — ${f.rationale}`).join('\n')+'\n\n## Tailored workflow\n\n'+(result.analysis.workflow||[]).map(w=>`### ${w.phase}\n${w.activities}\n\nRoles: ${w.roles}\nDeliverables: ${w.deliverables}\nEntry: ${w.entry}\nExit: ${w.exit}\nControls: ${w.controls}`).join('\n\n');generated.find(d=>d.id==='stories').content+='\n\n## Source-derived requirements\n\n'+result.analysis.requirements.map(q=>`- **${q.id}:** As an authorized stakeholder, I need ${q.statement.replace(/^the system shall /i,'')} so the documented need is traceable. Acceptance: ${q.acceptanceCriteria}`).join('\n');generated.push({id:'security',title:'Threat Model & Security Plan',type:'SEC',description:'Threats, privacy, security controls, and required human review',content:`# Threat Model & Security Plan — ${project.name}\n\n## Scope and assets\nCustomer and account data, credentials, project evidence, generated requirements, control sources, approvals, audit records, and model outputs. Confirm actual data classifications and trust boundaries with security and privacy owners.\n\n## Threat scenarios and proposed safeguards\n\n| Threat | Potential impact | Candidate safeguard / evidence | Owner |\n| --- | --- | --- | --- |\n| Unauthorized access or privilege misuse | Confidentiality or integrity loss | RBAC, MFA, least privilege, access review, immutable access logs | Security / IAM |\n| Prompt injection in uploaded evidence | Incorrect extraction or unsafe tool use | Treat sources as untrusted, isolate sessions, allowlist retrieval, restrict agent tools, test injection cases | AI / security |\n| Sensitive data leakage to a model or output | Privacy breach | Classify and mask before processing, provider allowlist, prompt/output filters, retention controls | Privacy / security |\n| Stale or inapplicable regulatory source | Wrong control interpretation | Source authority, jurisdiction, effective date, version and applicability record; compliance approval | Compliance / legal |\n| Conflicting stakeholder statements | Invalid requirements baseline | Conflict queue, cited sources, assigned decision owner and recorded resolution | Product owner |\n| Model error or unsupported claim | Incorrect specification or decision | Evidence citations, confidence, deterministic validation, human review, change and model-version audit | Product / model risk |\n| Data loss or service disruption | Operational and customer impact | Encryption in transit/at rest, backups, recovery objectives, incident response, rollback | Operations |\n\n## Security gates\nData classification and data-flow review before analysis; threat and privacy review before design; secure code and dependency checks during delivery; access, resilience, integration and prompt-injection tests before release; named human production-readiness approval.\n\n## Prototype security boundary\nFinSage local mode is an advisory prototype; this generated plan is a checklist. Actual authentication, MFA, encryption-at-rest, immutable audit storage, and institutional IAM must be implemented and verified for deployment.`});generated.push({id:'evaluation',title:'Evaluation & Pilot Plan',type:'EVAL',description:'Case study scenarios, prototype metrics, and conventional-process comparison',content:`# Evaluation & Pilot Plan — ${project.name}\n\n## Prototype measures\n\n| Measure | Current result | Interpretation |\n| --- | --- | --- |\n| Extracted requirements | ${result.analysis.metrics.extracted} | Count of candidate requirements; review all drafts |\n| Source traceability | ${result.analysis.metrics.traceability}% | Candidate source links; verify citation accuracy |\n| Completeness | ${result.analysis.metrics.completeness}% | Required fields populated; does not establish correctness |\n| Ambiguity findings | ${result.analysis.metrics.ambiguityFlags} | Items requiring stakeholder clarification |\n| Conflict findings | ${result.analysis.metrics.conflictFlags} | Candidate conflicts requiring owner resolution |\n| Candidate control coverage | ${result.analysis.metrics.candidateControlCoverage}% | Discovery suggestions only; not legal applicability |\n\n## Representative case-study scenarios\nDigital banking: account opening, access, transactions, service resilience. Loans: eligibility, decisions, explanations, exceptions, and audit trail. Payments: authorization, settlement, reconciliation, fraud controls. Fraud detection: alert triage, model governance, false-positive review. Insurance: quote, underwriting, claims, appeals. Regulatory reporting: source lineage, reconciliations, deadlines, approvals. Evaluate each using an institution-approved reference baseline.\n\n## Compare with conventional requirements work\nRun the same anonymized project packet through a conventional analyst-led process and FinSage. Compare elapsed time, requirement precision/recall against reviewer gold labels, citation accuracy, ambiguity/conflict detection, acceptance-criteria completeness, control-mapping precision, reviewer edits, and unresolved high-risk gaps. Report sample size and reviewer agreement; do not claim improvement until measured.\n\n## Pilot governance\nStart advisory-only with masked synthetic or approved data. Have business, security/privacy, compliance/legal, architecture, and operations reviewers assess output. Record decisions and changes, refresh approved knowledge sources, measure drift and errors, and expand use only after governance approval.`});generated.push({id:'interviews',title:'Stakeholder Interview Templates',type:'INT',description:'Role-specific adaptive interview prompts',content:'# Stakeholder Interview Templates\n\n'+Object.entries(result.interviewGuides||{}).map(([role,questions])=>`## ${titleCase(role)}\n\n${questions.map((q,i)=>`${i+1}. ${q}`).join('\n')}`).join('\n\n')});docs.splice(0,docs.length,...generated);currentAnalysis=result.analysis;addBackendArtefacts(result.analysis);syncRequirementDocuments();render(project,rec,docs,result.analysis);toast('Evidence-linked analysis is ready for review');}catch(error){toast(error.message||'Analysis failed');}finally{button.disabled=false;button.querySelector('span').textContent='Generate project analysis';}});
